# Code Generated by Sidekick is for learning and experimentation purposes only.
import time
from contextlib import contextmanager

from prometheus_client import Counter, Gauge, Histogram

HTTP_REQUESTS_TOTAL = Counter(
    "http_requests_total",
    "Total HTTP requests",
    ["method", "endpoint", "status_code"],
)

HTTP_REQUEST_LATENCY_SECONDS = Histogram(
    "http_request_latency_seconds",
    "HTTP request latency by endpoint",
    ["method", "endpoint"],
    buckets=(0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1, 2, 5, 10),
)

HOLD_CREATION_TOTAL = Counter(
    "hold_creation_total",
    "Hold creation success or failure",
    ["result"],
)

BOOKING_TOTAL = Counter(
    "booking_total",
    "Booking success or failure",
    ["result"],
)

PAYMENT_TOTAL = Counter(
    "payment_total",
    "Payment success or failure",
    ["result"],
)

REDIS_LOCK_ACQUISITION_SECONDS = Histogram(
    "redis_lock_acquisition_seconds",
    "Redis lock acquisition time",
    ["lock_name"],
    buckets=(0.0005, 0.001, 0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1, 2, 5),
)

REDIS_LOCK_CONTENTION_SECONDS = Histogram(
    "redis_lock_contention_seconds",
    "Redis lock contention wait time",
    ["lock_name"],
    buckets=(0.0005, 0.001, 0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1, 2, 5),
)

REDIS_LOCK_ACQUISITION_FAILURE_TOTAL = Counter(
    "redis_lock_acquisition_failure_total",
    "Redis lock acquisition failures",
    ["lock_name"],
)

HOLD_EXPIRY_TOTAL = Counter(
    "hold_expiry_total",
    "Expired holds detected",
)

SEAT_ALLOCATION_ATTEMPTS_TOTAL = Counter(
    "seat_allocation_attempts_total",
    "Seat allocation attempts",
    ["operation"],
)

SEAT_CONFLICTS_TOTAL = Counter(
    "seat_conflicts_total",
    "Seat conflicts",
    ["operation", "reason"],
)

DB_TRANSACTION_LATENCY_SECONDS = Histogram(
    "db_transaction_latency_seconds",
    "Database transaction latency",
    ["operation"],
    buckets=(0.001, 0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1, 2, 5, 10),
)

WEBSOCKET_CONNECTIONS_ACTIVE = Gauge(
    "websocket_connections_active",
    "Active websocket connections",
)

WEBSOCKET_CONNECTIONS_TOTAL = Counter(
    "websocket_connections_total",
    "Total websocket connections opened",
)


def normalize_lock_name(resource: str) -> str:
    return resource.split(":", 1)[0] if resource else "unknown"


def record_hold_creation(result: str) -> None:
    HOLD_CREATION_TOTAL.labels(result=result).inc()


def record_booking(result: str) -> None:
    BOOKING_TOTAL.labels(result=result).inc()


def record_payment(result: str) -> None:
    PAYMENT_TOTAL.labels(result=result).inc()


def record_hold_expiry() -> None:
    HOLD_EXPIRY_TOTAL.inc()


def record_seat_attempt(operation: str) -> None:
    SEAT_ALLOCATION_ATTEMPTS_TOTAL.labels(operation=operation).inc()


def record_seat_conflict(operation: str, reason: str) -> None:
    SEAT_CONFLICTS_TOTAL.labels(operation=operation, reason=reason).inc()


@contextmanager
def observe_db_transaction(operation: str):
    started = time.perf_counter()
    try:
        yield
    finally:
        DB_TRANSACTION_LATENCY_SECONDS.labels(operation=operation).observe(
            time.perf_counter() - started
        )


def status_is_success(value) -> bool:
    if value is None:
        return False
    normalized = str(getattr(value, "value", value)).strip().lower()
    return normalized in {
        "success",
        "succeeded",
        "completed",
        "confirmed",
        "booked",
        "captured",
        "authorized",
    }
